// ======= SET THIS TO true WHILE TESTING, false FOR REAL USE =======
const TESTING = true;

const TZ = 'Asia/Kolkata';

const SEC_BEFORE_FOLLOWUP_1 = TESTING ? 10 : 2 * 24 * 60 * 60;   // 2 days in prod
const SEC_BEFORE_FOLLOWUP_2 = TESTING ? 20 : 4 * 24 * 60 * 60;   // 4 days in prod
const SEC_BEFORE_FOLLOWUP_3 = TESTING ? 30 : 6 * 24 * 60 * 60;   // 6 days in prod
const SEC_BEFORE_CALL       = TESTING ? 40 : 2 * 24 * 60 * 60;   // call 2 days after Follow up 3
const SEC_CALL_LOCK         = TESTING ? 180 : 15 * 60;           // 'Calling' older than this is stale

const MAX_CALL_ATTEMPTS = 2;   // first call + one retry
const MAX_CALLS_PER_RUN = 1;   // ElevenLabs allows 3 at once; we stay strictly serial

const fmt = 'dd MMM yyyy HH:mm:ss';
const parse = (str) => (str ? DateTime.fromFormat(String(str), fmt, { zone: TZ }) : null);
const now = DateTime.now().setZone(TZ);

const rows = $input.all().map((item, index) => ({ d: item.json, index }));

// A call is live when some row is 'Calling' and was started recently.
// Anything older is treated as stale so the queue can never deadlock.
let callLocked = false;
for (const { d } of rows) {
  if ((d['Call Status'] || '').toString().trim().toLowerCase() !== 'calling') continue;
  const startedAt = parse(d['call_started_at']);
  const ageSec = startedAt && startedAt.isValid
    ? now.diff(startedAt, 'seconds').seconds
    : Number.MAX_SAFE_INTEGER;
  if (ageSec < SEC_CALL_LOCK) {
    callLocked = true;
    break;
  }
}

const callActions = [];
const emailActions = [];

for (const { d, index } of rows) {
  const status = parse(d['Status']);
  const f1 = parse(d['Follow up 1']);
  const f2 = parse(d['Follow up 2']);
  const f3 = parse(d['Follow up 3']);
  const retryAt = parse(d['call_retry_at']);
  const startedAt = parse(d['call_started_at']);

  const callStatus = (d['Call Status'] || '').toString().trim();
  const callStatusLower = callStatus.toLowerCase();
  const hasEmail = (d['Email'] || '').toString().trim().length > 0;
  const hasPhone = (d['phone_number'] || '').toString().trim().length > 0;
  const attempts = Number(d['call_attempt_count'] || 0);
  const callingAgeSec = startedAt && startedAt.isValid
    ? now.diff(startedAt, 'seconds').seconds
    : Number.MAX_SAFE_INTEGER;

  // Dead ends for the agent: bad number, both attempts used, or a real person has taken
  // over because a meeting / assessment was booked.
  const handedToHuman = callStatusLower.includes('human follow-up')
    || callStatusLower.includes('needs review');
  const noRetryEver = callStatusLower.includes('no retry')
    || callStatusLower.includes('exhausted')
    || handedToHuman;

  // ---------- calls (only one is released per run) ----------
  if (hasPhone && !noRetryEver && attempts < MAX_CALL_ATTEMPTS) {
    // Every lead waiting for its first call sits in the queue as 'Pending Call',
    // whether it came from a no-email row or from the end of the email sequence.
    if (callStatusLower === 'pending call') {
      const waitAfterFollowUps = hasEmail && f3 && f3.isValid;
      if (!waitAfterFollowUps) {
        callActions.push({ json: { ...d, nextFollowUp: 6, callReason: 'first call (no email lead)' }, pairedItem: index });
      } else if (now.diff(f3, 'seconds').seconds >= SEC_BEFORE_CALL) {
        callActions.push({ json: { ...d, nextFollowUp: 4, callReason: 'first call after follow-ups' }, pairedItem: index });
      }
      continue;
    }
    // The client asked to be called back, so the agent honours it at that time.
    // A booked meeting or assessment never reaches this branch: a human handles those.
    if (callStatusLower === 'callback scheduled' && retryAt && retryAt.isValid && now.toMillis() >= retryAt.toMillis()) {
      callActions.push({ json: { ...d, nextFollowUp: 7, callReason: 'callback requested by client' }, pairedItem: index });
      continue;
    }
    if (callStatusLower.includes('retry scheduled') && retryAt && retryAt.isValid && now.toMillis() >= retryAt.toMillis()) {
      callActions.push({ json: { ...d, nextFollowUp: 5, callReason: 'retry after no answer / declined / unreachable' }, pairedItem: index });
      continue;
    }
    if (callStatusLower === 'calling' && callingAgeSec >= SEC_CALL_LOCK) {
      callActions.push({ json: { ...d, nextFollowUp: 5, callReason: 'recover stale call' }, pairedItem: index });
      continue;
    }
    // Fallback for rows that finished the email sequence before 'Pending Call' existed.
    if (!callStatus && hasEmail && f3 && f3.isValid && now.diff(f3, 'seconds').seconds >= SEC_BEFORE_CALL) {
      callActions.push({ json: { ...d, nextFollowUp: 4, callReason: 'first call after follow-ups (legacy row)' }, pairedItem: index });
      continue;
    }
  }

  // ---------- follow-up emails ----------
  if (!hasEmail) continue;

  if (status && status.isValid && !d['Follow up 1'] && now.diff(status, 'seconds').seconds >= SEC_BEFORE_FOLLOWUP_1) {
    emailActions.push({ json: { ...d, nextFollowUp: 1 }, pairedItem: index });
  } else if (f1 && f1.isValid && !d['Follow up 2'] && now.diff(f1, 'seconds').seconds >= SEC_BEFORE_FOLLOWUP_2) {
    emailActions.push({ json: { ...d, nextFollowUp: 2 }, pairedItem: index });
  } else if (f2 && f2.isValid && !d['Follow up 3'] && now.diff(f2, 'seconds').seconds >= SEC_BEFORE_FOLLOWUP_3) {
    emailActions.push({ json: { ...d, nextFollowUp: 3 }, pairedItem: index });
  }
}

const releasedCalls = callLocked ? [] : callActions.slice(0, MAX_CALLS_PER_RUN);

return [...releasedCalls, ...emailActions];

