// Combine the lead row with the outbound-call response and take the queue lock,
// so no other lead is dialled until this call resolves or goes stale.
const TESTING = true; // keep in sync with Determine Due Follow-ups
const TZ = 'Asia/Kolkata';
const SEC_BEFORE_RETRY = TESTING ? 60 : 24 * 60 * 60;
const MAX_CALL_ATTEMPTS = 2;

const fmt = 'dd MMM yyyy HH:mm:ss';
const now = DateTime.now().setZone(TZ);

const lead = $('Is Call Due?').first().json;
const resp = $json || {};

const conversationId = resp.conversation_id || resp.conversationId || resp.call_sid || resp.callSid || null;
const attempts = Number(lead.call_attempt_count || 0) + 1;

// Leads are global, so no digit-count rules here. Only the telephony provider can say
// that a number does not exist, so we simply read what it told us.
const respText = JSON.stringify(resp).toLowerCase();
const notExistHints = [
  'does not exist',
  "doesn't exist",
  'nonexistent',
  'non-existent',
  'not in service',
  'no longer in service',
  'disconnected number',
  'unallocated',
  'not allocated',
  'unassigned',
  'number not found',
  'no route to destination',
  'invalid phone',
  'invalid number',
  'invalid to_number',
  'invalid destination'
];
const providerSaysNumberDead = notExistHints.some((hint) => respText.includes(hint));

let callStatus = 'Calling';
let lastOutcome = (lead.last_call_outcome || '').toString();
let retryAt = '';
let startedAt = now.toFormat(fmt);
let attemptCount = attempts;

// No conversation id means the call never started. Release the lock straight away
// instead of holding up the rest of the queue.
if (!conversationId) {
  startedAt = '';

  if (providerSaysNumberDead) {
    lastOutcome = 'Invalid Number';
    callStatus = 'Invalid Number - No Retry';
    attemptCount = MAX_CALL_ATTEMPTS;
  } else if (attempts < MAX_CALL_ATTEMPTS) {
    lastOutcome = 'Unreachable';
    callStatus = 'Unreachable - Retry Scheduled';
    retryAt = now.plus({ seconds: SEC_BEFORE_RETRY }).toFormat(fmt);
  } else {
    lastOutcome = 'Unreachable';
    callStatus = 'Unreachable - Retry Exhausted';
  }
}

return [{
  json: {
    ...lead,
    conversation_id: conversationId || '',
    call_attempt_count: attemptCount,
    call_started_at: startedAt,
    'Call Status': callStatus,
    last_call_outcome: lastOutcome,
    call_retry_at: retryAt
  }
}];

// ElevenLabs sends call_initiation_failure when a call cannot be connected.
//   number does not exist         -> Invalid Number   (never retried)
//   no answer                     -> Didn't Pick      (retry once)
//   busy / declined               -> Declined         (retry once)
//   switched off / out of network  -> Unreachable      (retry once)
//
// "Number does not exist" is decided by the carrier, never by digit counting,
// because these leads are global.
const TESTING = true; // keep in sync with Determine Due Follow-ups
const TZ = 'Asia/Kolkata';
const SEC_BEFORE_RETRY = TESTING ? 60 : 24 * 60 * 60;
const MAX_CALL_ATTEMPTS = 2;

const fmt = 'dd MMM yyyy HH:mm:ss';

const hook = $('Webhook Call Initiation Failure').first().json;
const payload = hook.body || hook;

const eventType = (payload.type || payload.event || '').toString().toLowerCase();
if (eventType && eventType !== 'call_initiation_failure') {
  return [];
}

const data = payload.data || payload;
const conversationId = (
  data.conversation_id ||
  data.conversationId ||
  payload.conversation_id ||
  payload.conversationId ||
  ''
).toString().trim();

if (!conversationId) {
  return [];
}

const reason = (data.failure_reason || data.failureReason || payload.failure_reason || '').toString().toLowerCase();
const meta = data.metadata || payload.metadata || {};
const sipCode = (meta.SipResponseCode || meta.sip_response_code || '').toString().trim();

// Fold every text field the provider sent into one string, so a carrier phrase like
// "the number you are trying to reach does not exist" is caught wherever it appears.
const signal = `${reason} ${JSON.stringify(meta)}`.toLowerCase();
const matches = (hints) => hints.some((hint) => signal.includes(hint));

// Carrier says the destination is not a real, reachable number.
const notExistHints = [
  'does not exist',
  "doesn't exist",
  'nonexistent',
  'non-existent',
  'not in service',
  'no longer in service',
  'disconnected number',
  'unallocated',
  'not allocated',
  'unassigned',
  'number not found',
  'invalid number',
  'invalid phone',
  'invalid destination',
  'wrong number',
  'no route to destination',
  'address incomplete'
];
// 404 Not Found, 410 Gone, 484 Address Incomplete, 604 Does Not Exist Anywhere
const notExistSip = ['404', '410', '484', '604'];

const declinedHints = ['busy', 'declined', 'decline', 'rejected', 'reject', 'canceled', 'cancelled'];
const declinedSip = ['486', '603'];

const noAnswerHints = ['no-answer', 'no_answer', 'noanswer', 'unanswered', 'timeout'];

const unreachableHints = ['unreachable', 'out of network', 'not reachable', 'switched off', 'unavailable', 'congestion', 'failed'];
const unreachableSip = ['480', '502', '503', '504'];

let outcome;
let retryable = true;

if (matches(notExistHints) || notExistSip.includes(sipCode)) {
  outcome = 'Invalid Number';
  retryable = false;
} else if (matches(declinedHints) || declinedSip.includes(sipCode)) {
  outcome = 'Declined';
} else if (matches(noAnswerHints) || sipCode === '408') {
  outcome = "Didn't Pick";
} else if (matches(unreachableHints) || unreachableSip.includes(sipCode)) {
  outcome = 'Unreachable';
} else {
  // failure_reason 'unknown' with no useful metadata: treat as a temporary problem.
  outcome = 'Unreachable';
}

const lead = $input
  .all()
  .map((item) => item.json)
  .find((row) => (row.conversation_id || '').toString().trim() === conversationId);

if (!lead || !(lead['Serial No'] || '').toString().trim()) {
  return [];
}

if ((lead['Call Status'] || '').toString().toLowerCase().includes('completed')) {
  return [];
}

const attempts = Number(lead.call_attempt_count || 1);

let callStatus;
let retryAt = '';
let attemptCount = attempts;

if (!retryable) {
  callStatus = `${outcome} - No Retry`;
  attemptCount = MAX_CALL_ATTEMPTS;
} else if (attempts < MAX_CALL_ATTEMPTS) {
  callStatus = `${outcome} - Retry Scheduled`;
  retryAt = DateTime.now().setZone(TZ).plus({ seconds: SEC_BEFORE_RETRY }).toFormat(fmt);
} else {
  callStatus = `${outcome} - Retry Exhausted`;
}

return [{
  json: {
    'Serial No': lead['Serial No'],
    'Call Status': callStatus,
    last_call_outcome: outcome,
    call_retry_at: retryAt,
    call_started_at: '',
    conversation_id: conversationId,
    call_attempt_count: attemptCount
  }
}];

// The agent's post-call webhook only sends lead_id, so look the row up to find the
// conversation we need to inspect and the counters we have to carry forward.
const hook = $('Webhook').first().json;
const body = hook.body || hook;

const leadId = (body.lead_id || body.leadId || '').toString().trim();
if (!leadId) {
  return [];
}

const row = $input
  .all()
  .map((item) => item.json)
  .find((r) => (r['Serial No'] || '').toString().trim() === leadId);

return [{
  json: {
    lead_id: leadId,
    body,
    conversation_id: row ? (row.conversation_id || '').toString().trim() : '',
    call_attempt_count: row ? Number(row.call_attempt_count || 1) : 1,
    callback_count: row ? Number(row.callback_count || 0) : 0,
    previous_call_status: row ? (row['Call Status'] || '').toString() : ''
  }
}];

// Decide what actually happened on an answered call, in this order:
//
//   1. a carrier recording answered            -> Invalid Number, never dialled again
//   2. answered but silent and very short      -> No Response, one more try
//   3. meeting / assessment booked            -> a REAL PERSON calls, agent never dials
//   4. client asked to be called back          -> the agent dials again at that time
//   5. anything else                           -> Completed
//
// The whole point of splitting 3 from 4: a booked meeting must never turn into a robot
// call, and a callback request must never be left sitting for a human.
const TESTING = true; // keep in sync with Determine Due Follow-ups
const TZ = 'Asia/Kolkata';
const SEC_BEFORE_RETRY = TESTING ? 60 : 24 * 60 * 60;
const MAX_CALL_ATTEMPTS = 2;
const MAX_CALLBACKS = 3;      // stop endless 'call me later' loops
const SHORT_CALL_SEC = 20;    // a real conversation is longer than this

const fmt = 'dd MMM yyyy HH:mm:ss';
const now = DateTime.now().setZone(TZ);

const lead = $('Resolve Conversation').first().json;
const body = lead.body || {};
const convo = $json || {};

const attempts = Number(lead.call_attempt_count || 1);
const callbackCount = Number(lead.callback_count || 0);

// ---------------------------------------------------------------- agent's answers
// Field names differ depending on how the data collection is set up in ElevenLabs,
// so accept the usual spellings rather than one hardcoded key.
const pick = (...keys) => {
  for (const src of [body, body.data || {}]) {
    for (const key of keys) {
      let value = src[key];
      if (value && typeof value === 'object' && 'value' in value) value = value.value;
      if (value !== undefined && value !== null && value.toString().trim() !== '') {
        return value.toString().trim();
      }
    }
  }
  return '';
};

let rawMeeting = pick(
  'meeting_datetime', 'meeting_schedule_time', 'meeting_time', 'meeting_scheduled_at',
  'assessment_datetime', 'assessment_schedule_time', 'assessment_time',
  'appointment_datetime', 'appointment_time', 'demo_datetime'
);
let rawCallback = pick('callback_datetime', 'callback_time', 'call_back_datetime', 'callback_at');

const outcomeText = `${body.lead_outcome || ''} ${body.next_action || ''} ${pick('meeting_type') || ''}`.toLowerCase();
const bookingWords = ['meeting', 'assessment', 'appointment', 'demo', 'consultation', 'audit', 'booked'];
const saysBooked = bookingWords.some((word) => outcomeText.includes(word));

// Safety net for agents that only have the callback field wired up: if the outcome says a
// booking was made, treat that timestamp as the meeting, never as a robot callback.
if (!rawMeeting && rawCallback && saysBooked) {
  rawMeeting = rawCallback;
  rawCallback = '';
}

let meetingType = pick('meeting_type', 'appointment_type');
if (!meetingType && rawMeeting) {
  if (outcomeText.includes('assessment') || outcomeText.includes('audit')) meetingType = 'Assessment';
  else if (outcomeText.includes('demo')) meetingType = 'Demo';
  else meetingType = 'Meeting';
}

// The agent may answer in any format, so try the realistic ones. If none parse we refuse to
// guess a dial time and ask a human to look instead.
const toDateTime = (raw) => {
  if (!raw) return null;
  const text = raw.toString().trim();
  const attemptsList = [
    () => DateTime.fromISO(text, { zone: TZ }),
    () => DateTime.fromSQL(text, { zone: TZ }),
    () => DateTime.fromRFC2822(text, { zone: TZ }),
    () => DateTime.fromFormat(text, fmt, { zone: TZ }),
    () => DateTime.fromFormat(text, 'dd MMM yyyy HH:mm', { zone: TZ }),
    () => DateTime.fromFormat(text, 'dd MMM yyyy hh:mm a', { zone: TZ }),
    () => DateTime.fromFormat(text, 'yyyy-MM-dd HH:mm', { zone: TZ }),
    () => DateTime.fromFormat(text, 'yyyy-MM-dd hh:mm a', { zone: TZ }),
    () => DateTime.fromFormat(text, 'dd/MM/yyyy HH:mm', { zone: TZ }),
    () => DateTime.fromFormat(text, 'dd-MM-yyyy HH:mm', { zone: TZ })
  ];
  for (const attempt of attemptsList) {
    try {
      const parsed = attempt();
      if (parsed && parsed.isValid) return parsed;
    } catch (err) {
      // try the next format
    }
  }
  return null;
};

// ---------------------------------------------------------------- was it a recording?
const announcementHints = [
  'does not exist',
  "doesn't exist",
  'not in service',
  'no longer in service',
  'out of service',
  'has been disconnected',
  'been disconnected',
  'unallocated',
  'not allocated',
  'unassigned',
  'not a valid number',
  'not a working number',
  'invalid number',
  'wrong number',
  'number you have dialed',
  'number you have dialled',
  'number you are trying to reach',
  'number you have called',
  'cannot be completed as dialed',
  'cannot be completed as dialled',
  'check the number',
  'number does not belong'
];

const transcript = Array.isArray(convo.transcript) ? convo.transcript : [];
// Whatever answered the call is transcribed as the 'user' side, so a recorded
// announcement shows up here just like a human would.
const otherSideText = transcript
  .filter((turn) => (turn && turn.role ? turn.role : '').toString().toLowerCase() !== 'agent')
  .map((turn) => (turn.message || turn.text || '').toString())
  .join(' ')
  .toLowerCase();

const heardAnnouncement = otherSideText.length > 0
  && announcementHints.some((hint) => otherSideText.includes(hint));

const meta = convo.metadata || {};
const durationSec = Number(meta.call_duration_secs || meta.callDurationSecs || 0);
const convoStatus = (convo.status || '').toString().toLowerCase();
// 'in-progress' means we fetched too early, so its transcript proves nothing.
const convoFinished = convoStatus !== '' && convoStatus !== 'in-progress' && convoStatus !== 'initiated';
const nobodySpoke = transcript.length > 0 && otherSideText.trim().length === 0;

// ---------------------------------------------------------------- verdict
let callStatus = 'Completed';
let leadOutcome = (body.lead_outcome || '').toString();
let lastOutcome = leadOutcome || 'answered';
let retryAt = '';
let attemptCount = attempts;
let newCallbackCount = callbackCount;
let meetingStamp = '';
let callbackStamp = '';
let meetingTypeOut = '';

if (heardAnnouncement) {
  // Not a real person. Never spend the second attempt on it.
  leadOutcome = 'invalid_number';
  lastOutcome = 'Invalid Number';
  callStatus = 'Invalid Number - No Retry';
  attemptCount = MAX_CALL_ATTEMPTS;
} else if (nobodySpoke && convoFinished && durationSec > 0 && durationSec <= SHORT_CALL_SEC) {
  // Answered, but nothing came back: voicemail, dead air or a beep. Worth one more try.
  leadOutcome = leadOutcome || 'no_response';
  lastOutcome = 'No Response';
  if (attempts < MAX_CALL_ATTEMPTS) {
    callStatus = 'No Response - Retry Scheduled';
    retryAt = now.plus({ seconds: SEC_BEFORE_RETRY }).toFormat(fmt);
  } else {
    callStatus = 'No Response - Retry Exhausted';
  }
} else if (rawMeeting) {
  // Interested and booked. A real person runs this one, so no dial time is ever set.
  const when = toDateTime(rawMeeting);
  meetingTypeOut = meetingType;
  meetingStamp = when ? when.toFormat(fmt) : rawMeeting; // keep the raw text if unparseable
  leadOutcome = leadOutcome || `${meetingType.toLowerCase()}_booked`;
  lastOutcome = `${meetingType} Booked`;
  callStatus = when
    ? `${meetingType} Scheduled - Human Follow-up`
    : `${meetingType} Scheduled - Needs Review`;
} else if (rawCallback) {
  // Not ready to talk now. The agent calls back itself.
  const when = toDateTime(rawCallback);
  leadOutcome = leadOutcome || 'callback_requested';
  lastOutcome = 'Callback Requested';

  if (!when) {
    // We will not guess a time and risk dialling at 3am.
    callbackStamp = rawCallback;
    callStatus = 'Callback Requested - Needs Review';
  } else if (callbackCount + 1 > MAX_CALLBACKS) {
    callbackStamp = when.toFormat(fmt);
    callStatus = 'Callback Limit Reached - Human Follow-up';
  } else {
    // A requested callback is not a failed-call retry, so it gets a fresh attempt budget.
    const dialAt = when.toMillis() < now.toMillis() ? now : when;
    callbackStamp = dialAt.toFormat(fmt);
    retryAt = dialAt.toFormat(fmt);
    callStatus = 'Callback Scheduled';
    newCallbackCount = callbackCount + 1;
    attemptCount = 0;
  }
}

const businessFields = heardAnnouncement
  ? { prospect_interest_level: '', business_challenge_identified: '', next_action: '' }
  : {
      prospect_interest_level: body.prospect_interest_level || '',
      business_challenge_identified: body.business_challenge_identified || '',
      next_action: body.next_action || ''
    };

return [{
  json: {
    'Serial No': lead.lead_id,
    'Call Status': callStatus,
    conversation_id: lead.conversation_id,
    call_attempt_count: attemptCount,
    call_started_at: '',
    call_retry_at: retryAt,
    last_call_outcome: lastOutcome,
    lead_outcome: leadOutcome,
    callback_datetime: callbackStamp,
    callback_count: newCallbackCount,
    meeting_datetime: meetingStamp,
    meeting_type: meetingTypeOut,
    ...businessFields
  }
}];

const TZ = 'Asia/Kolkata';
const fmt = 'dd MMM yyyy HH:mm:ss';
const now = DateTime.now().setZone(TZ);

const classified = $json;
const convo = $('Fetch Conversation').first().json || {};
const lead = $('Resolve Conversation').first().json || {};

const transcript = Array.isArray(convo.transcript) ? convo.transcript : [];

let formatted;
if (transcript.length === 0) {
  formatted = '(no transcript available)';
} else {
  formatted = transcript.map((turn) => {
    const role = (turn.role || '').toString().toLowerCase() === 'agent' ? 'Agent' : 'Client';
    const text = (turn.message || turn.text || '').toString().trim();
    return `${role}: ${text}`;
  }).join('\n');
}

const meta = convo.metadata || {};
const duration = Number(
  meta.call_duration_secs || meta.callDurationSecs || meta.duration || 0
);

return [{
  json: {
    ...classified,
    _transcript_serial: classified['Serial No'] || lead.lead_id || '',
    _transcript_name: lead.body ? (lead.body.client_name || lead.body.Name || '') : '',
    _transcript_conversation_id: classified.conversation_id || lead.conversation_id || '',
    _transcript_attempt: classified.call_attempt_count || lead.call_attempt_count || 1,
    _transcript_status: classified['Call Status'] || '',
    _transcript_timestamp: now.toFormat(fmt),
    _transcript_duration: duration,
    _transcript_text: formatted
  }
}];
